package com.tecsup.cita.service;import com.tecsup.cita.dto.*;import com.tecsup.cita.model.*;import com.tecsup.cita.repository.*;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.web.client.RestClient;import org.springframework.web.server.ResponseStatusException;
@Service public class CitaService{private final CitaRepository r;private final AtencionRepository ar;private final RestClient pacientes,medicos;public CitaService(CitaRepository r,AtencionRepository ar,RestClient.Builder b,@Value("${cita.url-pacientes}")String p,@Value("${cita.url-medicos}")String m){this.r=r;this.ar=ar;pacientes=b.clone().baseUrl(p).build();medicos=b.clone().baseUrl(m).build();}public List<Cita>listar(){return r.findAll();}public Cita obtener(Long id){return r.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Cita no encontrada"));}private void validarServicios(Long paciente,Long medico){try{pacientes.get().uri("/api/pacientes/{id}",paciente).retrieve().toBodilessEntity();}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Paciente no encontrado o servicio no disponible");}try{medicos.get().uri("/api/medicos/{id}",medico).retrieve().toBodilessEntity();}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Médico no encontrado o servicio no disponible");}}public Cita crear(CitaRequest d){validarServicios(d.idPaciente(),d.idMedico());Cita c=new Cita();c.setFecha(d.fecha());c.setHora(d.hora());c.setIdPaciente(d.idPaciente());c.setIdMedico(d.idMedico());c.setMotivo(d.motivo());return r.save(c);}public Cita actualizarEstado(Long id,String estado){Cita c=obtener(id);c.setEstado(estado);return r.save(c);}public Cita cancelar(Long id){return actualizarEstado(id,"CANCELADA");}public Atencion registrarAtencion(Long id,AtencionRequest d){Cita c=obtener(id);if("CANCELADA".equals(c.getEstado()))throw new ResponseStatusException(HttpStatus.CONFLICT,"No se registra atención para cita cancelada");c.setEstado("ATENDIDA");r.save(c);Atencion a=ar.findByCitaId(id).orElseGet(Atencion::new);a.setCita(c);a.setDiagnostico(d.diagnostico());a.setTratamiento(d.tratamiento());a.setObservaciones(d.observaciones());return ar.save(a);}public Atencion obtenerAtencion(Long id){obtener(id);return ar.findByCitaId(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Atención no registrada"));}public record AtencionRequest(@jakarta.validation.constraints.NotBlank String diagnostico,@jakarta.validation.constraints.NotBlank String tratamiento,String observaciones){}}
